@st.dialog("Инструкция по использованию", width="large")
def show_guide():
    st.write('Интеллектуальная система предназначена для распознавания рукописных цифр от 0 до 9 и сравнения результатов классификации при традиционном обучении с учителем (SL) и частично контролируемом обучении методом Self-Training (SSL). Основные элементы интерфейса обозначены цифрами на рисунке 1.')
    st.image(BytesIO(base64.b64decode(GUIDE_IMAGE)), caption='Рисунок 1 – Основные элементы пользовательского интерфейса', use_container_width=True)
    st.subheader("Назначение элементов интерфейса")
    st.write('1. Выбор алгоритма классификации. Позволяет выбрать используемую модель для предсказания: логистическую регрессию, метод опорных векторов (SVM), случайный лес (Random Forest) или метод ближайших соседей (KNN). Для использования необходимо раскрыть список и выбрать алгоритм. Выбор определяет, какие предварительно обученные модели SL и SSL будут применяться при распознавании.')
    st.write('2. Доля размеченных данных. Позволяет выбрать процент размеченных изображения при обучении модели: 1%, 2,5%, 5% или 10%. Необходимо раскрыть список и выбрать нужное значение. Параметр определяет загружаемую конфигурацию моделей и позволяет сравнивать результаты при различном количестве исходной разметки. Порог псевдоразметки SSL выбирается автоматически.')
    st.write('3. Поле ввода цифры. Предназначено для рисования цифры от 0 до 9. Следует удерживать левую кнопку мыши и нарисовать цифру белой линией на чёрном фоне. Это изображение будет передано на предварительную обработку и распознавание.')
    st.write('4. Кнопка «Очистить холст». Удаляет нарисованную цифру и возвращает поле ввода в исходное состояние. Используется для исправления изображения или ввода следующей цифры.')
    st.write('5. Кнопка «Распознать». Запускает обработку изображения и классификацию выбранными моделями SL и SSL. После нажатия изображение приводится к размеру 28 × 28 пикселей, затем отображаются распознанная цифра и оценка уверенности каждой модели в процентах.')
    st.subheader("Порядок использования")
    st.write('1. Для распознавания цифры необходимо выбрать алгоритм (1);')
    st.write('2. Указать долю размеченных данных (2);')
    st.write('3. Нарисовать цифру на холсте (3);')
    st.write('4. Нажать «Распознать» (5);')
    st.write('5. Для повторного ввода используется кнопка «Очистить холст» (4).')
    st.info('Отображаемая уверенность представляет собой оценку модели и не гарантирует правильность распознавания. Сравнение отдельных предсказаний служит для демонстрации работы системы.')

# Кнопка инструкции расположена в правом верхнем углу основной области.
_, guide_button_column = st.columns([5, 1.6])
with guide_button_column:
    if st.button("❔ Инструкция", use_container_width=True):
        show_guide()

st.title("Распознавание рукописных цифр")
st.write("Сравнение обучения с учителем (SL) и частично контролируемого обучения (SSL).")

model_label = st.selectbox("Алгоритм", list(MODEL_NAMES))
fraction_label = st.selectbox("Доля размеченных изображений при обучении", list(FRACTIONS), index=2)

algo = MODEL_NAMES[model_label]
fraction = FRACTIONS[fraction_label]

ssl_training_threshold = BEST_THRESHOLDS[algo][fraction]

st.caption(f"Порог уверенности для псевдоразметки SSL подбирается автоматически под выбранные условия для достижения наилучшего результата: {ssl_training_threshold:.1f}")
st.subheader("Нарисуйте цифру от 0 до 9")

if "canvas_version" not in st.session_state:
    st.session_state.canvas_version = 0

canvas = st_canvas(
    fill_color="rgba(0, 0, 0, 0)", stroke_width=18, stroke_color="#FFFFFF",
    background_color="#000000", width=280, height=280,
    drawing_mode="freedraw", update_streamlit=True,
    display_toolbar=False, key=f"digit_canvas_{st.session_state.canvas_version}",
)

if st.button("Очистить холст"):
    st.session_state.canvas_version += 1
    st.rerun()

if st.button("Распознать", type="primary", use_container_width=True):
    if canvas.image_data is None:
        st.warning("Сначала нарисуйте цифру.")
    else:
        try:
            digit, x = prepare_digit(canvas.image_data)
            algo = MODEL_NAMES[model_label]
            fraction = FRACTIONS[fraction_label]

            # Автоматически выбираем оптимальный порог SSL
            ssl_training_threshold = BEST_THRESHOLDS[algo][fraction]

            sl_file = f"{algo}_labeled_{fraction}_sl.joblib"
            ssl_file = f"{algo}_labeled_{fraction}_ssl_{ssl_training_threshold:.1f}.joblib"
            missing = [name for name in (sl_file, ssl_file) if not (MODEL_DIR / name).is_file()]
            if missing:
                st.error("Не найдены сохранённые модели: " + ", ".join(missing))
                st.info("Сначала выполните ячейку экспорта моделей в обучающем ноутбуке.")
            else:
                sl = load_model(sl_file)
                ssl = load_model(ssl_file)
                sl_result = prediction(sl, x)
                ssl_result = prediction(ssl, x)
                st.image(digit.resize((140, 140), Image.Resampling.NEAREST), caption="Изображение после обработки")
                col1, col2 = st.columns(2)
                for col, name, result in ((col1, "SL", sl_result), (col2, "SSL", ssl_result)):
                    with col:
                        st.subheader(name)
                        st.metric("Цифра", result[0])
                        st.metric("Уверенность", f"{result[1]:.1%}")
        except ValueError as exc:
            st.warning(str(exc))
        except Exception as exc:
            st.error(f"Не удалось выполнить распознавание: {exc}")

st.caption("SL и SSL используют одну долю исходных меток. Уверенность — оценка модели, а не гарантия правильного ответа.")